    if (v === ".") continue;
    const keys = [`r${r}${v}`, `c${c}${v}`, `b${Math.floor(r / 3)}${Math.floor(c / 3)}${v}`];
    if (keys.some(k => seen.has(k))) return false;
    keys.forEach(k => seen.add(k));
  }
  return true;
}

