class Trie {
  constructor() {
    this.root = {};
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) node = node[ch] ??= {};
    node.$ = true;
  }

  walk(s) {
    let node = this.root;
    for (const ch of s) {
      if (!(ch in node)) return null;
      node = node[ch];
    }
    return node;
  }

  search(word) {
    const node = this.walk(word);
    return node !== null && node.$ === true;
  }

  startsWith(prefix) {
    return this.walk(prefix) !== null;
  }
}
